<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {GraduationCap,Heart,BookOpen,MessageCircle,FlaskConical,ArrowLeft,ArrowRight,FileBadge,Plane,ClipboardList,Save} from '@lucide/vue'
import type {Player,RoomState,Student} from '../types'
import content from '../content.json'
import ScholarPortrait from './ScholarPortrait.vue'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number}>()
const emit=defineEmits<{act:[action:string,payload:Record<string,unknown>]}>()
const selected=ref(''),detailTab=ref<'research'|'history'>('research'),taskType=ref('paper'),taskTitle=ref(''),partner=ref(false),plan=ref(''),cancelConfirm=ref(false)
const students=computed(()=>props.player.students.filter(s=>!s.graduatedAt)),student=computed(()=>props.player.students.find(st=>st.id===selected.value)),quota=computed(()=>props.player.benefits.quota)
const candidates=computed(()=>props.player.admissions.candidates?.filter(c=>!c.hired)||[])
const works=computed(()=>student.value?props.player.portfolio.papers.filter(w=>w.authors.some(a=>a.id===student.value?.id)):[])
const patents=computed(()=>student.value?props.player.portfolio.patents.filter(w=>w.authors.some(a=>a.id===student.value?.id)):[])
const taskDef=computed(()=>content.research.tasks.find(t=>t.id===taskType.value))
const partnerName=computed(()=>Object.values(props.state.players).find(p=>p.id!==props.player.id)?.profile.name||'Yizi')
const degree=(v:string)=>v==='masters'?'硕士生':'博士生'
const date=(at:number)=>new Date(at).toLocaleDateString('zh-CN')
function open(st:Student){selected.value=st.id;detailTab.value='research';taskType.value='paper';taskTitle.value='';partner.value=false;plan.value=st.plan;cancelConfirm.value=false}
function careDisabled(st:Student){return props.busy||!!st.lastCareAt&&props.now<st.lastCareAt+4*3600000}
const taskState:Record<string,string>={working:'进行中',review:'审稿 / 授权中',completed:'已完成',cancelled:'已调整'}
</script>
<template>
 <div class="panel-heading"><div><span class="eyebrow">RESEARCH GROUP · PEOPLE & STORIES</span><h1>{{ student?student.name+'的研究生活':'我的小课题组' }}</h1></div><GraduationCap :size="31"/></div>
 <template v-if="student"><button class="text-button back-to-team" @click="selected=''"><ArrowLeft :size="15"/>返回课题组</button><div class="student-detail-head"><ScholarPortrait :seed="student.avatarSeed" :size="86" :label="student.name+'头像'"/><div><span class="small-label">{{ degree(student.degree) }} · {{ student.graduatedAt?'已毕业':'在读' }}</span><h2>{{ student.name }}</h2><p>{{ student.topic }}</p><small>{{ student.trait }} · 发表论文 {{ student.paper.total }} · 授权专利 {{ student.patent.total }}</small></div><span class="student-mood"><Heart :size="17"/>{{ student.wellbeing }}<small>最近心情</small></span></div>
  <div class="research-subnav"><button :class="{active:detailTab==='research'}" @click="detailTab='research'"><ClipboardList :size="15"/>研究与任务</button><button :class="{active:detailTab==='history'}" @click="detailTab='history'"><GraduationCap :size="15"/>履历与成果</button></div>
  <template v-if="detailTab==='research'"><aside v-if="student.contractWork" class="student-contract-notice"><ClipboardList :size="20"/><div><b>正在参与横向任务</b><p>{{ content.projects[student.contractWork.project]?.name }} · 占用期间个人研究进度减半，完成后恢复。</p><small>开始心情 −6，完成 −3；可以继续关怀与讨论研究。</small></div></aside><div class="student-progress-grid"><article><span>学业研究进度<b>{{ student.progress }} / {{ student.target }}</b></span><div class="progress-track"><i :style="{width:student.progress/student.target*100+'%'}"/></div><small>毕业还需心情达到 40，且处理完当前任务。</small></article><article><span>论文素材进度<b>{{ student.paper.progress }} / 100</b></span><div class="progress-track paper-progress"><i :style="{width:student.paper.progress+'%'}"/></div><small>空闲研究也会积累素材；布置论文任务后正式推进。</small></article><article><span>专利交底进度<b>{{ student.patent.progress }} / 60</b></span><div class="progress-track patent-progress"><i :style="{width:student.patent.progress/60*100+'%'}"/></div><small>授权后，师生署名进入课题组专利档案。</small></article></div>
   <article v-if="student.task" class="current-student-task"><span class="small-label">{{ taskState[student.task.status] }} · {{ content.research.tasks.find(t=>t.id===student!.task!.type)?.name }}</span><h3>{{ student.task.title }}</h3><div class="progress-track"><i :style="{width:student.task.progress/student.task.target*100+'%'}"/></div><p>{{ student.task.progress }} / {{ student.task.target }} <span v-if="student.task.dueAt&&student.task.status!=='completed'">· 约 {{ Math.max(0,Math.ceil((student.task.dueAt-now)/60000)) }} 分钟后完成</span></p><small v-if="student.task.partner">共同署名：{{ player.profile.name }}、{{ student.name }}、{{ partnerName }}</small><button v-if="student.task.status==='working'" class="text-button" :disabled="busy" @click="cancelConfirm=true">调整当前任务</button><div v-if="cancelConfirm" class="inline-confirm"><span>取消此任务，已支付的活动支持费不退；已积累的稿件素材保留。</span><button :disabled="busy" @click="emit('act','student_cancel',{id:student.id});cancelConfirm=false">确认调整</button><button @click="cancelConfirm=false">继续原任务</button></div></article>
   <form v-if="!student.graduatedAt" class="student-assignment" @submit.prevent="emit('act','student_task',{id:student.id,type:taskType,title:taskTitle,partner})"><div class="section-title"><h2>发布一个研究任务</h2><span>一次专心做一件事</span></div><label>任务类型<select v-model="taskType"><option v-for="t in content.research.tasks" :key="t.id" :value="t.id">{{ t.name }}{{ t.cost?' · '+t.cost+' 经费':'' }}</option></select></label><label>题目或主题（留空自动生成）<input v-model="taskTitle" maxlength="120" placeholder="例如：无人机桥梁巡检的数据融合方法"/></label><label v-if="taskType==='paper'" class="check-label"><input v-model="partner" type="checkbox"/>邀请 {{ partnerName }} 合作署名</label><p class="muted">{{ taskDef?.description }}</p><button class="primary" :disabled="busy||player.funds<(taskDef?.cost||0)||!!student.task&&student.task.status!=='completed'">发布任务<ArrowRight :size="16"/></button></form>
   <div v-if="!student.graduatedAt" class="care-actions"><button :disabled="careDisabled(student)" @click="emit('act','student_care',{id:student.id,mode:'guide'})"><BookOpen :size="15"/>聊聊研究<small>学业 +10 · 心情 +3</small></button><button :disabled="careDisabled(student)" @click="emit('act','student_care',{id:student.id,mode:'listen'})"><MessageCircle :size="15"/>听听近况<small>学业 +3 · 心情 +15</small></button><button :disabled="careDisabled(student)||player.funds<20" @click="emit('act','student_care',{id:student.id,mode:'sprint'})"><FlaskConical :size="15"/>一起做实验<small>学业 +16 · 心情 −12 · 20 经费</small></button></div><p v-if="student.lastCareAt&&now<student.lastCareAt+4*3600000" class="muted">交流后让同学消化一下，四小时后再来；任务仍会按时间推进。</p>
   <label class="student-plan">培养与下一步规划<textarea v-model="plan" rows="3" maxlength="400" placeholder="下一步想让同学完成什么，想去哪里交流？"/></label><button class="secondary" :disabled="busy" @click="emit('act','student_plan',{id:student.id,plan})"><Save :size="15"/>保存学生规划</button><button v-if="student.progress>=student.target&&!student.graduatedAt" class="primary wide graduate-button" :disabled="busy||student.wellbeing<40||!!student.contractWork||!!student.task&&student.task.status!=='completed'" @click="emit('act','student_graduate',{id:student.id})">一起准备毕业</button>
  </template>
  <template v-else><div class="student-cv-title"><span class="small-label">不急大学 · 学生游戏科研履历</span><h2>{{ student.name }} · {{ student.topic }}</h2><p>{{ student.plan }}</p></div><div class="section-title"><h2>论文与专利</h2><span>{{ works.length+patents.length }} 项保留记录</span></div><article v-for="w in [...works,...patents]" :key="w.id" class="publication-row"><component :is="w.number?FileBadge:BookOpen" :size="20"/><div><h3>{{ w.title }}</h3><p>{{ w.authors.map(a=>a.name).join('、') }}</p><small>{{ w.number||w.journal }} · {{ w.publishedAt?date(w.publishedAt):'历史成果' }}</small></div></article><p v-if="!works.length&&!patents.length" class="empty-note">第一项成果还在路上。布置一个论文或专利任务，完成后会在这里留档。</p><div class="section-title"><h2>学术经历</h2><span>报告、参会、访学与研究任务</span></div><ol class="student-timeline"><li v-for="a in [...student.activities].reverse()" :key="a.id" :class="{withdrawn:a.status!=='completed'}"><time>{{ date(a.at) }}</time><h3>{{ a.title }}</h3><span>{{ a.venue }} · {{ a.status==='completed'?'已完成':'未形成有效学术经历' }}</span><p>{{ a.summary }}</p></li></ol><p v-if="!student.activities.length" class="empty-note">可以委派同学参加来信里的学术活动，或为 TA 安排报告、访学。</p><div class="section-title"><h2>任务记录</h2></div><article v-for="t in [...student.taskHistory].reverse()" :key="t.id" class="task-history-row"><span>{{ taskState[t.status] }}</span><b>{{ t.title }}</b><small>{{ t.completedAt?date(t.completedAt):'' }}</small></article></template>
 </template>
 <template v-else><div class="team-overview"><div><span>第 {{ player.admissions.year }} 学年 · 现实 {{ state.academicYearDays }} 天</span><h2>每位同学，都有自己的研究故事。</h2><p>可以安排论文、专利、报告和访学。成果与经历会进入课题组档案和学生履历。</p></div><span><b>{{ students.length }} / {{ quota.capacity }}</b>在组同学</span></div><div class="quota-row"><span>硕士指标 <b>{{ player.admissions.masters }} / {{ quota.masters }}</b></span><span>博士指标 <b>{{ player.admissions.phds }} / {{ quota.phds }}</b></span><span>累计毕业 <b>{{ player.graduates }} 位</b></span></div>
  <div class="roster-grid"><button v-for="st in player.students" :key="st.id" class="roster-card" @click="open(st)"><ScholarPortrait :seed="st.avatarSeed" :size="66" :label="st.name+'头像'"/><div><span class="small-label">{{ degree(st.degree) }} · {{ st.graduatedAt?'已毕业':'在读' }}</span><h2>{{ st.name }}</h2><p>{{ st.topic }}</p></div><ArrowRight :size="16"/><div class="roster-meters"><span>学业 {{ st.progress }} / {{ st.target }}<i :style="{width:st.progress/st.target*100+'%'}"/></span><span>论文 {{ st.paper.progress }} / 100<i :style="{width:st.paper.progress+'%'}"/></span></div><small class="roster-current">{{ st.task&&st.task.status!=='completed'?st.task.title:st.graduatedAt?'已经从这里出发':'正在自由探索研究素材' }}</small><span class="roster-footer"><b><Heart :size="12"/>{{ st.wellbeing }}</b><small>论文 {{ st.paper.total }} · 专利 {{ st.patent.total }} · 查看详情</small></span></button></div><div v-if="!player.students.length" class="empty-state"><GraduationCap :size="34"/><p>第一位同学还没入组。翻翻招生小册吧。</p></div>
  <div class="section-title"><h2>本学年招生小册</h2><span>每位同学都有独立头像和课题</span></div><div class="candidate-grid"><article v-for="c in candidates" :key="c.id"><ScholarPortrait :seed="c.id" :size="55" :label="c.name+'头像'"/><span class="small-label">{{ degree(c.degree) }}申请</span><h3>{{ c.name }}</h3><p>{{ c.topic }}</p><small>{{ c.trait }}</small><button class="secondary wide" :disabled="busy||students.length>=quota.capacity||player.admissions[c.degree]>=quota[c.degree]||player.funds<(c.degree==='masters'?100:160)" @click="emit('act','student_hire',{id:c.id})">欢迎入组 · {{ c.degree==='masters'?100:160 }} 经费</button></article></div><p class="gentle-footer">每 6 小时一轮研究反馈，最多存 4 轮；不需要一直在线照顾，论文审稿与访学也会在离线期间完成。</p>
 </template>
</template>
